def pm(title, doi, pub, pmid, pmc=None, note="초록 확인"):
    p = f"{pub}, " + (f"{pmc}, " if pmc else "") + f"PMID {pmid}"
    url = f"https://doi.org/{doi}" if doi else f"https://pubmed.ncbi.nlm.nih.gov/{pmid}/"
    return {"title": f"{title} ({note})", "url": url, "publisher": p, "accessed": A}
